"""Phase 2 kernel-core driver (CLAUDE.md §14): bands -> reduce -> CTPR -> π,
wired end-to-end against the provisional EIS config.

Produces the three reportable artifacts (§12): the floor-dominance table,
the CTPR 18/18 propagation table, and the full-lattice monotonicity check
-- plus a manifest (§13) so every artifact here can be regenerated by one
command: `python3 -m experiments.phase2_kernel_core` from the repo root.

Labelling, per §12 and explicit instruction: the T1/T2 exhaustive pass
below is machine-checked implementation conformance, not independent
empirical validation. π is a meet of monotone maps; monotonicity and
non-compensation hold by that construction. This script's exhaustive scan
is a regression guard confirming the code implements that construction
correctly (it would fail only on a formula/dict typo), not a claim about
detector behaviour or real-world evidence.

All results here run under calibration_status: provisional (§14: "Phases
1-7 run under calibration_status: provisional"). The EIS config's ROC
curves are synthetic placeholders, not measured detector characterisations
-- see config/eis.v0.json.
"""

import itertools
import json
import pathlib
import sys

REPO_ROOT = pathlib.Path(__file__).resolve().parent.parent
if str(REPO_ROOT) not in sys.path:
    sys.path.insert(0, str(REPO_ROOT))

from trust_kernel import ctpr as ctpr_mod
from trust_kernel import policy as policy_mod
from trust_kernel.bands import DIMENSIONS, TrustLevel, meet, load_eis_config
from provenance import manifest as manifest_mod
from tests import orphan_check

CONFIG_DIR = REPO_ROOT / "config"
ARTIFACTS_DIR = REPO_ROOT / "artifacts"
PROVENANCE_DIR = REPO_ROOT / "provenance"

LEVELS = (TrustLevel.LOW, TrustLevel.MED, TrustLevel.HIGH)


def _pi(raw_dims, edges, strict, lenient):
    effective = ctpr_mod.apply_ctpr(raw_dims, edges)
    return policy_mod.policy(effective, strict, lenient)


def build_floor_dominance_table(strict, lenient):
    rows = []
    for d in DIMENSIONS:
        for level in LEVELS:
            floor = policy_mod.crit(d, level, strict, lenient)
            rows.append({
                "dimension": d,
                "class": "strict" if d in strict else "lenient",
                "level": level.name,
                "floor": floor.name,
            })
    return rows


def build_ctpr_table(edges):
    rows = []
    for (parent, child), fsi_level, child_level in itertools.product(edges, LEVELS, LEVELS):
        raw_dims = {d: TrustLevel.HIGH for d in DIMENSIONS}
        raw_dims["FSI"] = fsi_level
        raw_dims[child] = child_level
        effective = ctpr_mod.apply_ctpr(raw_dims, edges)
        expected = meet(child_level, fsi_level)  # g == identity, ground truth
        actual = effective[child]
        rows.append({
            "edge": f"{parent}->{child}",
            "fsi_level": fsi_level.name,
            "child_level": child_level.name,
            "effective_child": actual.name,
            "matches_expected": actual == expected,
        })
    return rows


def run_monotonicity_scan(edges, strict, lenient):
    checked = 0
    violations = []
    for combo in itertools.product(LEVELS, repeat=len(DIMENSIONS)):
        base = dict(zip(DIMENSIONS, combo))
        pi_base = _pi(base, edges, strict, lenient)
        for d in DIMENSIONS:
            if base[d] == TrustLevel.HIGH:
                continue
            bumped = dict(base)
            bumped[d] = TrustLevel(base[d] + 1)
            pi_bumped = _pi(bumped, edges, strict, lenient)
            checked += 1
            if pi_bumped < pi_base:
                violations.append({
                    "base": {k: v.name for k, v in base.items()},
                    "bumped_dimension": d,
                    "pi_base": pi_base.name,
                    "pi_bumped": pi_bumped.name,
                })
    return {
        "lattice_size": 3 ** len(DIMENSIONS),
        "covering_pairs_checked": checked,
        "violations": violations,
        "monotone": len(violations) == 0,
    }


def _write_json(obj, path):
    path.write_text(json.dumps(obj, indent=2, sort_keys=True) + "\n")


def _write_markdown_table(rows, columns, path, title):
    lines = [f"# {title}", ""]
    lines.append("| " + " | ".join(columns) + " |")
    lines.append("|" + "|".join(["---"] * len(columns)) + "|")
    for row in rows:
        lines.append("| " + " | ".join(str(row[c]) for c in columns) + " |")
    path.write_text("\n".join(lines) + "\n")


def main():
    ARTIFACTS_DIR.mkdir(exist_ok=True)
    PROVENANCE_DIR.mkdir(exist_ok=True)

    # Orphan check (L8->L6 relattice, changelog 2026-07-19): fail loudly if
    # any config still references the removed Safety/Context dimension,
    # claim types, or source_ids -- see tests/orphan_check.py for why this
    # exists as a standalone scan rather than relying solely on the
    # existing fail-closed config validators.
    orphan_config_paths = {
        "crit_table": CONFIG_DIR / "crit_table.json",
        "ctpr": CONFIG_DIR / "ctpr.json",
        "eis_v0": CONFIG_DIR / "eis.v0.json",
        "claim_registry": CONFIG_DIR / "claim_registry.json",
        "key_registry": CONFIG_DIR / "key_registry.json",
    }
    orphan_hits = orphan_check.find_orphan_references(orphan_config_paths)
    if orphan_hits:
        raise SystemExit(f"ORPHAN CHECK FAILED: {orphan_hits}")

    crit_raw, strict, lenient = policy_mod.load_crit_table(CONFIG_DIR / "crit_table.json")
    ctpr_raw, edges = ctpr_mod.load_ctpr_config(CONFIG_DIR / "ctpr.json")
    eis_raw, eis_derived = load_eis_config(CONFIG_DIR / "eis.v0.json")

    floor_table = build_floor_dominance_table(strict, lenient)
    ctpr_table = build_ctpr_table(edges)
    monotonicity = run_monotonicity_scan(edges, strict, lenient)

    floor_json = ARTIFACTS_DIR / "phase2_floor_dominance.json"
    floor_md = ARTIFACTS_DIR / "phase2_floor_dominance.md"
    ctpr_json = ARTIFACTS_DIR / "phase2_ctpr_table.json"
    ctpr_md = ARTIFACTS_DIR / "phase2_ctpr_table.md"
    mono_json = ARTIFACTS_DIR / "phase2_monotonicity_summary.json"

    _write_json(floor_table, floor_json)
    _write_markdown_table(floor_table, ["dimension", "class", "level", "floor"], floor_md, "Floor-dominance table (§4, §12)")
    _write_json(ctpr_table, ctpr_json)
    _write_markdown_table(
        ctpr_table, ["edge", "fsi_level", "child_level", "effective_child", "matches_expected"],
        ctpr_md, "CTPR propagation table (§4, §12: \"CTPR 18/18\")",
    )
    _write_json(monotonicity, mono_json)

    m = manifest_mod.build_manifest(
        repo_root=REPO_ROOT,
        experiment_name="phase2_kernel_core",
        config_paths={
            "crit_table": CONFIG_DIR / "crit_table.json",
            "ctpr": CONFIG_DIR / "ctpr.json",
            "eis_v0": CONFIG_DIR / "eis.v0.json",
        },
        params={
            "alpha_bp": eis_raw["alpha_bp"],
            "beta_bp": eis_raw["beta_bp"],
            "ctpr_g": ctpr_raw["g"],
        },
        artifact_paths={
            "floor_dominance_json": floor_json,
            "floor_dominance_md": floor_md,
            "ctpr_table_json": ctpr_json,
            "ctpr_table_md": ctpr_md,
            "monotonicity_summary_json": mono_json,
        },
        calibration_status=eis_raw["calibration_status"],
        seeds={"note": "not applicable -- exhaustive deterministic enumeration, no sampling"},
    )
    manifest_path = PROVENANCE_DIR / "phase2_kernel_core_manifest.json"
    manifest_mod.write_manifest(m, manifest_path)

    print(f"Orphan check (L8->L6, changelog 2026-07-19): {'CLEAN' if not orphan_hits else orphan_hits}")

    ctpr_pass = sum(1 for r in ctpr_table if r["matches_expected"])
    print(f"CTPR: {ctpr_pass}/{len(ctpr_table)}")
    print(f"Floor-dominance table: {len(floor_table)} rows ({len(DIMENSIONS)} dimensions x 3 levels)")
    print(
        f"Monotonicity: lattice_size={monotonicity['lattice_size']} "
        f"covering_pairs_checked={monotonicity['covering_pairs_checked']} "
        f"monotone={monotonicity['monotone']}"
    )
    print(
        "\nLabel (§12): the monotonicity/CTPR pass above is machine-checked "
        "implementation conformance -- pi is constructed as a meet of "
        "monotone maps, so this scan is a regression guard on that "
        "construction, not independent empirical validation."
    )
    print(f"\nArtifacts written to {ARTIFACTS_DIR}")
    print(f"Manifest written to {manifest_path}")

    if not monotonicity["monotone"] or ctpr_pass != len(ctpr_table):
        sys.exit(1)


if __name__ == "__main__":
    main()
